  }]]},{move_to={ -16.474361, 0.1, -0.723995 }, json=[[{"GUID": "7bde4d","Name": "Custom_Tile","Transform": {"posX": 75.54,"posY": 35.73566,"posZ": -51.81992,"rotX": 0.0176363252,"rotY": 179.997818,"rotZ": 0.0801224858,"scaleX": 13.1043873,"scaleY": 1.0,"scaleZ": 13.1043873},"Nickname": "Quest Claimer","Description": "","GMNotes": "","ColorDiffuse": {"r": 0.249997467,"g": 0.249997467,"b": 0.249997467},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": false,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/1838029047142282273/02D1E8D3841249A4BC881E8BE22302315D145739/","ImageSecondaryURL": "","ImageScalar": 1.0,"WidthScale": 0.0,"CustomTile": {"Type": 0,"Thickness": 0.1,"Stackable": false,"Stretch": true}},"LuaScript": "local CARD_SCALE_XZ = 2.36\r\n\r\nlocal _scriptingZone = false\r\n\r\nlocal pickedUp = false\r\n\r\nfunction onLoad(save_state)\r\n      createScriptingZone()\r\n      Wait.time(resetScriptingZone,0.3)\r\n      createButtons()\r\n      wait_id = Wait.time(updateFox, 1, -1)\r\n      wait_id = Wait.time(updateRabbit, 1, -1)\r\n      wait_id = Wait.time(updateMouse, 1, -1)\r\nend\r\nmouse = 1\r\nrabbit = 1\r\nfox = 1\r\nwait_id = 0\r\n\r\n\r\nfunction updateFox()\r\n  fox = 1\r\n  items = Physics.cast({\r\n      origin       = self.positionToWorld({-0.2185, 0.1, -0.475}),\r\n      direction    = self.getTransformUp(),\r\n      type         = 3,\r\n      size         = {3, 0.1, 6},\r\n      max_distance = 2,\r\n  })\r\n  for _, item in ipairs(items) do\r\n    if item.hit_object.tag == \"Card\" then\r\n        addFox()\r\n\r\n    elseif item.hit_object.tag == \"Deck\" then\r\n        for _, card in ipairs(item.hit_object.getObjects()) do\r\n            addFox()\r\n        end\r\n    end\r\n  end\r\n  if (fox >= 6) then fox = \"-\" end\r\n  self.editButton({index=0,label=tostring(fox)})\r\n\r\nend\r\n\r\nfunction addFox()\r\n  fox = fox + 1\r\nend\r\n\r\nfunction updateRabbit()\r\n  rabbit = 1\r\n  items = Physics.cast({\r\n      origin       = self.positionToWorld({-0.2185, 0.1, 0.105}),\r\n      direction    = self.getTransformUp(),\r\n      type         = 3,\r\n      size         = {3, 0.1, 6},\r\n      max_distance = 2,\r\n  })\r\n\r\n  for _, item in ipairs(items) do\r\n    if item.hit_object.tag == \"Card\" then\r\n        addRabbit()\r\n\r\n    elseif item.hit_object.tag == \"Deck\" then\r\n        for _, card in ipairs(item.hit_object.getObjects()) do\r\n            addRabbit()\r\n        end\r\n    end\r\n  end\r\n  if (rabbit >= 6) then rabbit = \"-\" end\r\n  self.editButton({index=1,label=tostring(rabbit)})\r\n\r\nend\r\n\r\nfunction addRabbit()\r\n  rabbit = rabbit + 1\r\nend\r\n\r\nfunction updateMouse()\r\n  mouse = 1\r\n  items = Physics.cast({\r\n      origin       = self.positionToWorld({-0.2185, 0.1, 0.210 + 0.485}),\r\n      direction    = self.getTransformUp(),\r\n      type         = 3,\r\n      size         = {3, 0.1, 6},\r\n      max_distance = 2,\r\n  })\r\n\r\n  for _, item in ipairs(items) do\r\n    if item.hit_object.tag == \"Card\" then\r\n        addMouse()\r\n\r\n    elseif item.hit_object.tag == \"Deck\" then\r\n        for _, card in ipairs(item.hit_object.getObjects()) do\r\n            addMouse()\r\n        end\r\n    end\r\n  end\r\n  if (mouse >= 6) then mouse = \"-\" end\r\n  self.editButton({index=2,label=tostring(mouse)})\r\n\r\nend\r\n\r\nfunction addMouse()\r\n  mouse = mouse + 1\r\nend\r\n\r\n\r\n\r\nfunction addCard()\r\n  n = 1;\r\n    suit = suit:lower()\r\n    if suit == \"fox\" then\r\n        fox = fox +1\r\n    elseif suit == \"mouse\" then\r\n        mouse = mouse + 1\r\n    elseif suit == \"rabbit\" then\r\n        rabbit= rabbit + 1\r\n    end\r\nend\r\n\r\n\r\n\r\nfunction createButtons()\r\n  self.createButton({\r\n    click_function = \"nothing\",\r\n    function_owner = self,\r\n    label = '1',\r\n    position = {-0.2185, 0.15, -0.475},\r\n    scale = {0.45, 0.00, 0.45},\r\n    width = 0,\r\n    height = 0,\r\n    font_color={1,1,1,1},\r\n    font_size = 120,\r\n\r\n})\r\nself.createButton({\r\n    click_function = \"nothing\",\r\n    function_owner = self,\r\n    label = '1',\r\n    position = {-0.2185, 0.15, 0.105},\r\n    scale = {0.45, 0.00, 0.45},\r\n    width = 0,\r\n    height = 0,\r\n    font_color={1,1,1,1},\r\n    font_size = 120,\r\n\r\n})\r\nself.createButton({\r\n    click_function = \"nothing\",\r\n    function_owner = self,\r\n    label = '1',\r\n    position = {-0.2185, 0.15, 0.210 + 0.48},\r\n    scale = {0.45, 0.00, 0.45},\r\n    width = 0,\r\n    height = 0,\r\n    font_color={1,1,1,1},\r\n    font_size = 120,\r\n\r\n})\r\n\r\n\r\nend\r\n\r\n\r\n\r\nfunction onPickUp(player_color)\r\n  _scriptingZone = nil\r\n  pickedUp = true\r\nend\r\n\r\nfunction onDrop(playerColor)\r\n    if _scriptingZone == nil then createScriptingZone() end\r\n    Wait.time(resetScriptingZone, 0.3)\r\n    pickedUp = false\r\nend\r\n\r\nfunction onRotate()\r\n    if _scriptingZone == nil and pickedUp == false then createScriptingZone() end\r\n    Wait.time(resetScriptingZone, 0.3)\r\nend\r\n\r\n-------------------------------------------------------------------------------\r\n\r\nfunction isRelevantCard(enterObject)\r\n    assert(type(enterObject) == 'userdata')\r\n    return enterObject.tag == 'Card' and enterObject.hasTag(\"Smallfry\")\r\nend\r\n\r\nfunction onObjectEnterScriptingZone(zone, enterObject)\r\n    if not enterObject then\r\n        return\r\n    end\r\n    if zone == _scriptingZone and isRelevantCard(enterObject) then\r\n        enterObject.setScale({\r\n            x = CARD_SCALE_XZ,\r\n            y = 1,\r\n            z = CARD_SCALE_XZ,\r\n        })\r\n    end\r\n\r\n    local size = enterObject.getBoundsNormalized().size\r\nend\r\n\r\nfunction onObjectLeaveScriptingZone(zone, leaveObject)\r\n    if not leaveObject then\r\n        return\r\n    end\r\n    if zone == _scriptingZone and isRelevantCard(leaveObject) then\r\n        leaveObject.setScale({\r\n            x = 1.18,\r\n            y = 1,\r\n            z = 1.18,\r\n        })\r\n    end\r\nend\r\n\r\n-------------------------------------------------------------------------------\r\n\r\nfunction createScriptingZone()\r\n    assert(not _scriptingZone)\r\n\r\n    local zoneName = self.getGUID() .. ' SCRIPTING ZONE'\r\n\r\n    local function getScriptingZone()\r\n        for _, object in ipairs(getAllObjects()) do\r\n            if object.tag == 'Scripting' and object.getName() == zoneName then\r\n                return object\r\n            end\r\n        end\r\n    end\r\n\r\n    _scriptingZone = getScriptingZone() or spawnObject({\r\n        type              = 'ScriptingTrigger',\r\n        position          = self.getPosition(),\r\n        rotation          = self.getRotation(),\r\n        sound             = false,\r\n        snap_to_grid      = false\r\n    })\r\n    _scriptingZone.setName(zoneName)\r\nend\r\n\r\n-- Attaching via joint prevents mat from being movable (???).\r\n-- Just reposition zone when mat moves.\r\nfunction resetScriptingZone()\r\n\r\n    local angleY = self.getRotation().y\r\n    local posX = self.getPosition().x\r\n    local posZ = self.getPosition().z\r\n\r\n    local angle = -1.18 - (math.pi/180 * angleY) + math.pi\r\n\r\n    local offsetX = math.cos(angle) * 2.5\r\n    local offsetZ = math.sin(angle) * 1.5\r\n\r\n    local posy = Vector({posX + offsetX,self.getPosition().y,posZ + offsetZ})\r\n    local roty = self.getRotation()\r\n\r\n    if _scriptingZone != nil then\r\n      _scriptingZone.setPosition({x = posy.x, y = posy.y, z = posy.z})\r\n      _scriptingZone.setRotation({x = roty.x, y = roty.y, z = roty.z})\r\n\r\n      local size = self.getBoundsNormalized().size\r\n      _scriptingZone.setScale({\r\n          x = 3,\r\n          y = 12,  -- 4 is enough, could make larger to be safe\r\n          z = 18,\r\n      })\r\n    end\r\nend","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -0.07179,"y": 0.0999818444,"z": -0.473538369},"Rotation": {"x": -1.31740163E-09,"y": 359.9735,"z": 1.75093362E-08}},{"Position": {"x": -0.07141617,"y": 0.100016221,"z": 0.108126447},"Rotation": {"x": -5.93499028E-09,"y": 359.991425,"z": 3.75237974E-09}},{"Position": {"x": -0.07048862,"y": 0.100046,"z": 0.6918604},"Rotation": {"x": -6.29031627E-09,"y": 359.973145,"z": 2.79326517E-08}}]
