  {move_to={ -1.37378, 0.064376, 2.783675 }, json=[[{"GUID": "8a274d","Name": "Custom_Assetbundle","Transform": {"posX": 90.64,"posY": 35.68,"posZ": -48.31,"rotX": 0.0168439839,"rotY": 180.0203,"rotZ": 0.07991002,"scaleX": 6.600006,"scaleY": 6.600006,"scaleZ": 6.600006},"Nickname": "Koffin Keeper","Description": "Holds & counts meeples for Root's 'Coffin Makers' card.\n\nMouseover & press '1' to de-activate!\n\n*MEEPLES MUST HAVE NAMES THAT INCLUDE THE WORD 'WARRIOR' OR THEY WILL NOT BE COUNTED!*\n\nMade by Nevakanezah","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/1736675300477909275/E4BA5F3F5AB199EFD8977FEFF9EC8126F4238ACC/","AssetbundleSecondaryURL": "","MaterialIndex": 1,"TypeIndex": 1,"LoopingEffectIndex": 0},"LuaScript": "----#include root\\coffinkeeper\r\nwarriors = 0\r\nwait_id = 0\r\n\r\nfunction onLoad(save_state)\r\n    createButtons()\r\n    wait_id = Wait.time(updateButtons, 1, -1)\r\nend\r\n\r\nfunction onDestroy()\r\n    Wait.stop(wait_id)\r\nend\r\n\r\nfunction nothing()\r\nend\r\n\r\nfunction addWarrior(name)\r\n    name = name:lower()\r\n\tif string.match(name, \"warrior\") then\r\n\t\twarriors = warriors + 1\r\n    end\r\nend\r\n\r\nfunction createButtons()\r\n  self.createButton({\r\n      click_function = \"nothing\",\r\n      function_owner = self,\r\n      label = '0',\r\n\t  position = {0.21, 1.7, 0.98}, \r\n\t  rotation = {14, 90, -90}, \r\n\t  scale = {0.5, 0.5, 0.5}, \r\n\t  width = 0,\r\n      height = 0,\r\n\t  font_size = 450\r\n  })\r\nend\r\n\r\nfunction updateButtons()\r\n    warriors = 0\r\n    items = Physics.cast({\r\n        origin       = self.positionToWorld({0, 0, 0.1}),\r\n        direction    = self.getTransformUp(),\r\n\t\torientation  = Vector(self.getRotation()) + Vector({0, 87, 0}), --{0, 87, 0},\r\n        type         = 3,\r\n        size         = {11.5, 7, 7},\r\n        max_distance = 2\r\n    })\r\n    for _, item in ipairs(items) do\r\n        if item.hit_object.tag == \"Figurine\" then\r\n            addWarrior(item.hit_object.getName())\r\n        end\r\n    end\r\n\r\n    self.editButton({index=0,label=tostring(math.floor(warriors/5))})\r\nend\r\n----#include root\\coffinkeeper","LuaScriptState": "","XmlUI": "","States": {"1": {"GUID": "b5014a","Name": "Custom_Assetbundle","Transform": {"posX": 58.9902344,"posY": 35.65214,"posZ": -80.68422,"rotX": 0.01684398,"rotY": 180.0203,"rotZ": 0.07991003,"scaleX": 5.70000267,"scaleY": 5.70000267,"scaleZ": 5.70000267},"Nickname": "Koffin Keeper","Description": "Holds & counts meeples for Root's 'Coffin Makers' card.\n\nMouseover & press '2' to activate!\n\n*MEEPLES MUST HAVE NAMES THAT INCLUDE THE WORD 'WARRIOR' OR THEY WILL NOT BE COUNTED!*\n\nMade by Nevakanezah","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/1736675300477798481/E3D9619EF83A2523492157D05EE53F7B53FF1946/","AssetbundleSecondaryURL": "","MaterialIndex": 1,"TypeIndex": 1,"LoopingEffectIndex": 0},"LuaScript": "","LuaScriptState": "","XmlUI": ""}}
