\r\ntooltip = \"VP-\"\r\n}\r\n--dominationButton = {\r\n--click_function = 'dominationActivePurp',\r\n--label = 'Victory Mode\\nDOMINANCE',\r\n--function_owner = self,\r\n--position = {0, 0.05, - 2.65},\r\n--rotation = {0, 0, 0},\r\n--width = 1600,\r\n--height = 600,\r\n--font_size = 200,\r\n--tooltip = 'Change Victory Mode to Domination'\r\n--}\r\n--dominationButtonBack = {\r\n--click_function = 'dominationActiveBackPurp',\r\n--label = 'Victory Mode\\nVICTORY POINTS',\r\n--function_owner = self,\r\n--position = {0, 0.05, - 2.65},\r\n--rotation = {0, 0, 0},\r\n--width = 1600,\r\n--height = 600,\r\n--font_size = 200,\r\n--tooltip = 'Change Victory Mode to Victory Points'\r\n--}\r\nrollButton = {\r\nclick_function = \"click_roll\",\r\nfunction_owner = self,\r\nposition = {0, 0.1, 0},\r\nrotation = {0, 0, 0},\r\nwidth= 900,\r\nheight = 900,\r\ncolor= {0, 0, 0, 0},\r\ntooltip= \"Combat\"\r\n}\r\ndrawButton = {\r\nclick_function = \"draw\",\r\nfunction_owner = self,\r\nposition = { 0, 0.1, 1.4},\r\nrotation = {0, 0, 0},\r\nwidth = 450,\r\nheight = 450,\r\ncolor = {0, 0, 0, 0},\r\ntooltip = \"Draw\"\r\n}\r\n\r\nfunction onLoad(saved_data)\r\n--if saved_data ~= \"\" and saved_data ~= nil then\r\n--local loaded_data = JSON.decode(saved_data)\r\n--index = loaded_data.purpleIndex\r\n--else\r\nindex = 0\r\n--end\r\n\r\n--Loads the save of any active dice and deletes them\r\nif saved_data ~= \"\" then\r\nlocal loaded_data = JSON.decode(saved_data)\r\nfor _, guid in ipairs(loaded_data) do\r\nlocal obj = getObjectFromGUID(guid)\r\nif obj ~= nil then\r\ndestroyObject(obj)\r\nend\r\nend\r\ncurrentDice = {}\r\nelse\r\ncurrentDice = {}\r\nend\r\n\r\nself.createButton(rollButton)\r\nself.createButton(plusButton)\r\nself.createButton(minusButton)\r\nself.createButton(drawButton)\r\nend\r\n\r\nfunction addVP(object, color)\r\nlocal changed_position = {}\r\nchanged_position[1] = start_position[1]\r\nchanged_position[2] = start_position[2]\r\nchanged_position[3] = start_position[3]\r\nindex = index + 1\r\nif index <= 0 then\r\nindex = 0\r\nelseif index <= 29 then\r\nchanged_position[direction] = start_position[direction] + increase * (index * step)\r\nnew_position = changed_position\r\nprintToAll(Player[color].steam_name .. \" VP +1 (\"..(index - 1)..\"+1)\", stringColorToRGB(color))\r\nelse\r\nindex = 30\r\nchanged_position[direction] = start_position[direction] + increase * (index * step)\r\nend\r\n\r\nif index==30 then\r\nprintToAll(Player[color].steam_name .. \" WIN!\", stringColorToRGB(color))\r\nend\r\nvpObject = getObjectFromGUID(VP_guid)\r\nvpObject.setPositionSmooth(changed_position)\r\nend\r\n\r\nfunction removeVP(object, color)\r\nlocal changed_position = {}\r\nchanged_position[1] = start_position[1]\r\nchanged_position[2] = start_position[2]\r\nchanged_position[3] = start_position[3]\r\nindex = index - 1\r\nif index <= 0 then\r\nindex = 0\r\nelseif index <= 29 then\r\nchanged_position[direction] = start_position[direction] + increase * (index * step)\r\nnew_position = changed_position\r\nprintToAll(Player[color].steam_name .. \" VP -1 (\"..(index - 1)..\"-1)\", stringColorToRGB(color))\r\nelse\r\nindex = 30\r\nchanged_position[direction] = start_position[direction] + increase * (index * step)\r\nend\r\n\r\nvpObject = getObjectFromGUID(VP_guid)\r\nvpObject.setPositionSmooth(changed_position)\r\nend\r\n\r\n\r\nfunction dominationActivePurp(object, color)\r\n--self.removeButton(0)\r\n--self.removeButton(1)\r\n--self.removeButton(2)\r\n--self.createButton(dominationButtonBack)\r\n--broadcastToAll(\"Marquise de Cat changed their Victory Mode to DOMINATION!\")\r\n--getObjectFromGUID(purpleVP_guid).setPosition(self.positionToWorld({0,-2,0}))\r\n--getObjectFromGUID(purpleVP_guid).setLock(true)\r\nend\r\n\r\nfunction dominationActiveBackPurp(object)\r\n--self.removeButton(0)\r\n--self.createButton(addButton)\r\n--self.createButton(removeButton)\r\n--self.createButton(dominationButton)\r\n--getObjectFromGUID(purpleVP_guid).setPosition(purple[index])\r\n--getObjectFromGUID(purpleVP_guid).setLock(false)\r\n--broadcastToAll(\"Marquise de Cat PV token is back on the VP track\")\r\nend\r\n\r\n\r\n\r\nfunction onSave()\r\n--Put variables to save into a table\r\n--local data_to_save = {purpleIndex = index}\r\n--saved_data = JSON.encode(data_to_save)\r\n--return saved_data\r\n\r\nif #currentDice > 0 then\r\nlocal currentDiceGUIDs = {}\r\nfor _, obj in ipairs(currentDice) do\r\nif obj ~= nil then\r\ntable.insert(currentDiceGUIDs, obj.getGUID())\r\nend\r\nend\r\nsaved_data = JSON.encode(currentDiceGUIDs)\r\nelse\r\nsaved_data = \"\"\r\nend\r\nreturn saved_data\r\nend\r\n\r\n--Click function, spawns new dice and waits for a pause to do the rolling\r\nfunction click_roll(_, color)\r\n--Dice spam protection, can be disabled up at top of script\r\nlocal diceCount = 0\r\nfor _ in pairs(currentDice) do\r\ndiceCount = diceCount + 1\r\nend\r\nlocal denyRoll = false\r\nif dieLimit > 0 and diceCount >= dieLimit then\r\ndenyRoll = true\r\nend\r\n--Check for if click is allowed\r\nif rollInProgress == nil and denyRoll == false then\r\n--Spawns dice\r\nlocal spawnedDie = spawnObject({\r\ntype=dieType,\r\nposition = findGlobalPosWithLocalDirection(130),\r\nrotation = randomRotation(),\r\nscale = {dieSize,dieSize,dieSize} -- getRelativeScale()\r\n})\r\nif dieType == \"Custom_Dice\" then\r\nspawnedDie.setCustomObject({\r\nimage = dieImage,\r\ntype = ref_customDieSides[tostring(dieSides)]\r\n})\r\nrotation_values = {\r\n{value=0, rotation={x=27, y=0, z=72}},\r\n{value=1, rotation={x=27, y=0, z=144}},\r\n{value=2, rotation={x=27, y=0, z=288}},\r\n{value=3, rotation={x=333, y=180, z=180}},\r\n{value=0, rotation={x=90, y=180, z=0}},\r\n{value=1, rotation={x=27, y=0, z=216}},\r\n{value=2, rotation={x=333, y=180, z=36}},\r\n{value=3, rotation={x=270, y=180, z=0}},\r\n{value=0, rotation={x=27, y=0, z=0}},\r\n{value=1, rotation={x=333, y=180, z=108}},\r\n{value=2, rotation={x=333, y=108, z=324}},\r\n{value=3, rotation={x=333, y=36, z=252}},\r\n}\r\nspawnedDie.setRotationValues(rotation_values)\r\nend\r\nspawnedDie.interactable = false\r\nspawnedDie.setLock(true)\r\nif dieColorOverwrite ~= false then\r\nspawnedDie.setColorTint(dieColorOverwrite)\r\nelseif diePlayerColor == true then\r\nspawnedDie.setColorTint(stringColorToRGB(color))\r\nclone_parameters = {position = findGlobalPosWithLocalDirection(0),rotation=randomRotation()}\r\nlocal spawnedDie2 = spawnedDie.clone(clone_parameters);\r\nlocal pos = findGlobalPosWithLocalDirection(-120)\r\nspawnedDie2.setPositionSmooth(pos, false, true)\r\ntable.insert(currentDice, spawnedDie)\r\ntable.insert(currentDice, spawnedDie2)\r\nend\r\n--Timer starting\r\nTimer.destroy(\"clickRoller_\"..self.getGUID())\r\nTimer.create({\r\nidentifier=\"clickRoller_\"..self.getGUID(), delay=waitBeforeRoll,\r\nfunction_name=\"rollDice\", function_owner=self,\r\nparameters = {color = color}\r\n})\r\nelseif rollInProgress == false then\r\ncleanupDice()\r\nclick_roll(_, color)\r\nelse\r\nPlayer[color].broadcast(\"Roll in progress.\", {0.8, 0.2, 0.2})\r\nend\r\nend\r\n\r\n--Rolls all the dice and then launches monitoring\r\nfunction rollDice(p)\r\nrollInProgress = true\r\n\r\nfunction coroutine_rollDice()\r\nfor _, die in ipairs(currentDice) do\r\ndie.setLock(false)\r\ndie.randomize()\r\nwait(0.1)\r\nend\r\nmonitorDice(p.color)\r\nreturn 1\r\nend\r\n\r\nstartLuaCoroutine(self, \"coroutine_rollDice\")\r\nend\r\n\r\n--Monitors dice to come to rest\r\nfunction monitorDice(color)\r\nfunction coroutine_monitorDice()\r\nrepeat\r\nlocal allRest = true\r\nfor _, die in ipairs(currentDice) do\r\nif die ~= nil and die.resting == false then\r\nallRest = false\r\nend\r\nend\r\ncoroutine.yield(0)\r\nuntil allRest == true\r\n--Announcement\r\nif announce_total==true or announce_each==true then\r\ndisplayResults(color)\r\nend\r\nwait(0.1)\r\nrollInProgress = false\r\n\r\nfor _, die in ipairs(currentDice) do\r\ndie.interactable = true\r\nend\r\n\r\n--Auto die removal\r\nif removalDelay ~= -1 then\r\n--Timer starting\r\nTimer.destroy(\"clickRoller_cleanup_\"..self.getGUID())\r\nTimer.create({\r\nidentifier=\"clickRoller_cleanup_\"..self.getGUID(),\r\nfunction_name=\"cleanupDice\", function_owner=self,\r\ndelay=removalDelay,\r\n})\r\nend\r\n\r\nreturn 1\r\nend\r\nstartLuaCoroutine(self, \"coroutine_monitorDice\")\r\nend\r\n\r\n--After roll broadcasting and cleanup\r\nfunction displayResults(color)\r\nlocal total = 0\r\nlocal resultTable = {}\r\nlocal larger = 0\r\nlocal smaller = 0\r\n\r\n--Tally result info\r\nfor _, die in ipairs(currentDice) do\r\nif die ~= nil then\r\nlocal value = die.getRotationValue()\r\nsmaller = value\r\nif larger > value then\r\nsmaller = value\r\nelseif larger < value then\r\nsmaller = larger\r\nlarger = value\r\nend\r\nend\r\nend\r\n\r\ntable.insert(resultTable, larger)\r\ntable.insert(resultTable, smaller)\r\n\r\n--String assembly\r\nlocal s = \"\"\r\nif announce_each == true then\r\nfor i, v in ipairs(resultTable) do\r\nif not (s == \"\") then\r\ns = s .. \" and \"\r\nend\r\ns = s .. v\r\nend\r\nend\r\nif announce_player == true then\r\ns = Player[color].steam_name .. \"|\" .. s\r\nend\r\nbroadcastToAll(s, stringColorToRGB(color))\r\nend\r\n\r\n--Die cleanup\r\nfunction cleanupDice()\r\nfor _, die in ipairs(currentDice) do\r\nif die ~= nil then\r\ndestroyObject(die)\r\nend\r\nend\r\nTimer.destroy(\"clickRoller_cleanup_\"..self.getGUID())\r\nrollInProgress = nil\r\ncurrentDice = {}\r\nend\r\n\r\n--Calculate the scale dice should be, relative to the rolling mat\r\nfunction getRelativeScale()\r\nlocal object = self\r\nlocal matScale = object.getScale()\r\nreturn matScale * dieSize\r\nend\r\n\r\n--Finds a position, rotated around the Y axis, using distance you want + angle\r\n--oPos is object pos, oRot=object rotation, distance = how far, angle = angle in degrees\r\nfunction findGlobalPosWithLocalDirection(angle)\r\nlocal object, distance = self, radialOffset * self.getScale().x\r\nlocal oPos, oRot = object.getPosition(), object.getRotation()\r\nlocal posX = oPos.x + math.sin( math.rad(angle+oRot.y) ) * distance\r\nlocal posY = oPos.y + heightOffset\r\nlocal posZ = oPos.z + math.cos( math.rad(angle+oRot.y) ) * distance\r\nreturn {x=posX, y=posY, z=posZ}\r\nend\r\n\r\n--Gets a random rotation vector\r\nfunction randomRotation()\r\n--Credit for this function goes to Revinor (forums)\r\n--Get 3 random numbers\r\nlocal u1 = math.random();\r\nlocal u2 = math.random();\r\nlocal u3 = math.random();\r\n--Convert them into quats to avoid gimbal lock\r\nlocal u1sqrt = math.sqrt(u1);\r\nlocal u1m1sqrt = math.sqrt(1-u1);\r\nlocal qx = u1m1sqrt *math.sin(2*math.pi*u2);\r\nlocal qy = u1m1sqrt *math.cos(2*math.pi*u2);\r\nlocal qz = u1sqrt *math.sin(2*math.pi*u3);\r\nlocal qw = u1sqrt *math.cos(2*math.pi*u3);\r\n--Apply rotation\r\nlocal ysqr = qy * qy;\r\nlocal t0 = -2.0 * (ysqr + qz * qz) + 1.0;\r\nlocal t1 = 2.0 * (qx * qy - qw * qz);\r\nlocal t2 = -2.0 * (qx * qz + qw * qy);\r\nlocal t3 = 2.0 * (qy * qz - qw * qx);\r\nlocal t4 = -2.0 * (qx * qx + ysqr) + 1.0;\r\n--Correct\r\nif t2 > 1.0 then t2 = 1.0 end\r\nif t2 < -1.0 then ts = -1.0 end\r\n--Convert back to X/Y/Z\r\nlocal xr = math.asin(t2);\r\nlocal yr = math.atan2(t3, t4);\r\nlocal zr = math.atan2(t1, t0);\r\n--Return result\r\nreturn {math.deg(xr),math.deg(yr),math.deg(zr)}\r\nend\r\n\r\n--Coroutine delay, in seconds\r\nfunction wait(time)\r\nlocal start = os.time()\r\nrepeat coroutine.yield(0) until os.time() > start + time\r\nend\r\n\r\n--Data tables\r\nref_customDieSides = {[\"4\"]=0, [\"6\"]=1, [\"8\"]=2, [\"10\"]=3, [\"12\"]=4, [\"20\"]=5}\r\n\r\nfunction draw(obj, color)\r\n--local objInZone = deckZone.getObjects()\r\ngetObjectFromGUID(\"8062a0\").deal(1, color)\r\nprintToAll(Player[color].steam_name .. \" drew a card\", stringColorToRGB(color))\r\n--for _, obj in ipairs(objInZone) do\r\n--if obj.tag == \"Deck\" or obj.tag == \"Card\" then\r\n -- getObjectFromGUID(obj.guid).deal(1, color)\r\n--end\r\n--end\r\nend","LuaScriptState": "","XmlUI": "","GUID": "c0679a"}]]},}}

