  }]]},{move_to={ 1.697483, 0.1, 11.753232 }, json=[[{"GUID": "3d159f","Name": "Custom_Tile","Transform": {"posX": 93.7099838,"posY": 35.7140923,"posZ": -39.34,"rotX": 0.0176354349,"rotY": 179.998566,"rotZ": 0.08012267,"scaleX": 5.37,"scaleY": 1.0,"scaleZ": 5.37},"Nickname": "Quest Freshener","Description": "","GMNotes": "","ColorDiffuse": {"r": 0.249997616,"g": 0.249997616,"b": 0.249997616},"Tags": ["Quest"],"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": false,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": false,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/1838029017026322236/9C074168B8525B89A406899698C7E15A6F43175C/","ImageSecondaryURL": "","ImageScalar": 1.0,"WidthScale": 0.0,"CustomTile": {"Type": 0,"Thickness": 0.1,"Stackable": false,"Stretch": true}},"LuaScript": "local CARD_SCALE_XZ = 2.36\r\n\r\nlocal _scriptingZone = false\r\n\r\nlocal pickedUp = false\r\nfunction onLoad(save_state)\r\n      createScriptingZone()\r\n      Wait.time(resetScriptingZone,0.3)\r\n      -- self.createButton({\r\n      --     click_function=\"click_refillDeck\", function_owner=self,\r\n      --     position={-1.94,0.1,0.14}, height=300, width=200, color={225,1,1,0}\r\n      -- })\r\n\r\n      -- {4.55, 1.06, 10.34} --board\r\n      -- {14.98, 1.15, 9.55} --discard\r\n      pos_discard = {-0.957, 0.178, 0.222}\r\n      pos_draw = {0.957, 0.178, 0.222}\r\n      pos_discard_top = {-0.957, 2, 0.222}\r\n      fox_loc = {2.0853, 2, 0.1574}\r\n      rabbit_loc = {0.7033, 2, 0.1573}\r\n      mouse_loc = {-0.6839, 2, 0.1572}\r\n      bird_loc = {-2.0679, 2, 0.1571}\r\n      positions = {}\r\n      last_card = {}\r\n      one_left = false\r\n\r\n\r\n      --This is how I found the positions to check for cards\r\n      --That GUID was a card I put on it\r\n      --local pos = self.positionToLocal(getObjectFromGUID(\"a6b1bd\").getPosition())\r\n      --print(pos.x)\r\n      --print(pos.y)\r\n      --print(pos.z)\r\n\r\n      --This is which way is face down for a card or deck relative to the tool\r\n\r\nend\r\n\r\nfunction onPickUp(player_color)\r\n  _scriptingZone = nil\r\n  pickedUp = true\r\nend\r\n\r\nfunction onDrop(playerColor)\r\n    if _scriptingZone == nil then createScriptingZone() end\r\n    Wait.time(resetScriptingZone, 0.3)\r\n    pickedUp = false\r\nend\r\n\r\nfunction onRotate()\r\n    if _scriptingZone == nil and pickedUp == false then createScriptingZone() end\r\n    Wait.time(resetScriptingZone, 0.3)\r\nend\r\n\r\n-------------------------------------------------------------------------------\r\n\r\nfunction isRelevantCard(enterObject)\r\n    assert(type(enterObject) == 'userdata')\r\n    return enterObject.tag == 'Card' and enterObject.hasTag(\"Smallfry\")\r\nend\r\n\r\nfunction onObjectEnterScriptingZone(zone, enterObject)\r\n\r\n    if not enterObject then\r\n        return\r\n    end\r\n\r\n    if zone == _scriptingZone and isRelevantCard(enterObject) then\r\n        enterObject.setScale({\r\n            x = CARD_SCALE_XZ,\r\n            y = 1,\r\n            z = CARD_SCALE_XZ,\r\n        })\r\n    end\r\n\r\n    local size = enterObject.getBoundsNormalized().size\r\nend\r\n\r\nfunction onObjectLeaveScriptingZone(zone, leaveObject)\r\n    if not leaveObject then\r\n        return\r\n    end\r\n    if zone == _scriptingZone and isRelevantCard(leaveObject) then\r\n        leaveObject.setScale({\r\n            x = 1.18,\r\n            y = 1,\r\n            z = 1.18,\r\n        })\r\n    end\r\nend\r\n\r\n-------------------------------------------------------------------------------\r\n\r\nfunction createScriptingZone()\r\n    assert(not _scriptingZone)\r\n\r\n    local zoneName = self.getGUID() .. ' SCRIPTING ZONE'\r\n\r\n    local function getScriptingZone()\r\n        for _, object in ipairs(getAllObjects()) do\r\n            if object.tag == 'Scripting' and object.getName() == zoneName then\r\n                return object\r\n            end\r\n        end\r\n    end\r\n\r\n    _scriptingZone = getScriptingZone() or spawnObject({\r\n        type              = 'ScriptingTrigger',\r\n        position          = self.getPosition(),\r\n        rotation          = self.getRotation(),\r\n        sound             = false,\r\n        snap_to_grid      = false\r\n    })\r\n    _scriptingZone.setName(zoneName)\r\nend\r\n\r\n-- Attaching via joint prevents mat from being movable (???).\r\n-- Just reposition zone when mat moves.\r\nfunction resetScriptingZone()\r\n\r\n    local angleY = self.getRotation().y\r\n    local posX = self.getPosition().x\r\n    local posZ = self.getPosition().z\r\n\r\n    local angle = -1.18 - (math.pi/180 * angleY) + math.pi\r\n\r\n    local offsetX = math.cos(angle) * 0.0\r\n    local offsetZ = math.sin(angle) * 1.0\r\n\r\n    local posy = Vector({posX + offsetX,self.getPosition().y,posZ + offsetZ})\r\n    local roty = self.getRotation()\r\n\r\n    if _scriptingZone != nil then\r\n      _scriptingZone.setPosition({x = posy.x, y = posy.y, z = posy.z})\r\n      _scriptingZone.setRotation({x = roty.x, y = roty.y, z = roty.z})\r\n\r\n      local size = self.getBoundsNormalized().size\r\n      _scriptingZone.setScale({\r\n          x = 12,\r\n          y = 12,  -- 4 is enough, could make larger to be safe\r\n          z = 4,\r\n      })\r\n    end\r\nend\r\n\r\n\r\n\r\n\r\nfunction click_refillDeck()\r\n  local discardItemList = findObjectsAtPosition({self.positionToWorld(pos_discard)})\r\n\r\n    --This gets all decks and cards in the discard area\r\n\r\n    print(discardedItemList)\r\n    --This is where we want to put those discarded cards\r\n    print(\"success\")\r\n    -- local pos = self.positionToWorld(pos_draw)\r\n    -- --This is how we want the card rotated\r\n    -- local rot = self.getRotation()\r\n    -- rot = {rot.x+rot_offset.x, rot.y+rot_offset.y, rot.z+rot_offset.z}\r\n    --\r\n    -- --This is going through and placing all llcards/decks with this info\r\n    -- for _, obj in ipairs(discardItemList) do\r\n    --     obj.setPositionSmooth(pos, false, true)\r\n    --     obj.setRotationSmooth(rot)\r\n    -- end\r\n    --\r\n    --\r\n    -- --We check if any cards were moved before we go to shuffle\r\n    -- if #discardItemList > 0 then\r\n    --     --Finally, we start a short timer to shuffle the cards after they move\r\n    --     Timer.destroy(\"shuffleTimer_\"..self.getGUID())\r\n    --     Timer.create({\r\n    --         identifier = \"shuffleTimer_\"..self.getGUID(),\r\n    --         function_name = \"timer_shuffle\",\r\n    --         function_owner = self,\r\n    --         delay = 1\r\n    --     })\r\n    -- end\r\nend\r\n","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -1.94064367,"y": -1.2837816E-05,"z": 0.1446142},"Rotation": {"x": -1.27845041E-07,"y": 0.0242458154,"z": 1.81237272E-06}},{"Position": {"x": -1.09695733,"y": -1.4322839E-05,"z": 0.144087911},"Rotation": {"x": 2.67321649E-08,"y": 0.00105049193,"z": 180.0}},{"Position": {"x": -0.00282143,"y": 6.57234432E-06,"z": 0.14404574},"Rotation": {"x": 1.02784758E-08,"y": 0.00105049193,"z": 180.0}},{"Position": {"x": 1.09836721,"y": 4.09723725E-06,"z": 0.146929085},"Rotation": {"x": 2.26660046E-09,"y": 0.00105049193,"z": 180.0}},{"Position": {"x": 1.94151068,"y": 2.73343176E-06,"z": 0.145575568},"Rotation": {"x": 1.19551942E-07,"y": 0.00105049193,"z": 180.0}}]
