    local color = from_color:lerp(to_color, (1/steps)*x)\r\n                for _, object in ipairs(objects) do\r\n                    object.highlightOn(color)\r\n                end\r\n                waitTime(step_time)\r\n            end\r\n            waitTime(0.1)\r\n            for x=1, steps do\r\n                local color = to_color:lerp(from_color, (1/steps)*x)\r\n                for _, object in ipairs(objects) do\r\n                    object.highlightOn(color)\r\n                end\r\n                waitTime(step_time)\r\n            end\r\n            return 1\r\n        end\r\n        startLuaCoroutine(self, 'co_change')\r\n    end\r\n    change()\r\n    return Wait.time(change, 4.5, -1)\r\nend\r\n\r\nfunction find_objects_by_names(names)\r\n    local objects = {}\r\n    for _, o in ipairs(getAllObjects()) do\r\n        for _, n in ipairs(names) do\r\n            if o.getName() == n then\r\n                table.insert(objects, o)\r\n            end\r\n        end\r\n    end\r\n    return objects\r\nend\r\n\r\n----#include ..\\utils\\wait\nfunction waitTime(x)\r\n    local time = os.clock()\r\n    while time + x > os.clock() do\r\n        coroutine.yield()\r\n    end\r\nend\r\n\n----#include ..\\utils\\wait\n\n----#include root\\highlighter","LuaScriptState": "","XmlUI": ""
