              end
            end

            -- Knaves Cards Spawning in Draft
            if t.getName() == "Knaves of the Deepwood" then
              spawnKnaveCards()
              for _,v in ipairs(getObjectsWithTag("Captain Cards")) do
                v.shuffle()
                v.shuffle()    
                v.shuffle()
                v.shuffle()
                v.shuffle()
