          vec = vec * Vector(15.5, 1, 15.5)
      end
      local new_pos = pos + vec
      new_pos.y = new_pos.y - 0.1
      spawnObjectJSON({
          json              = v.json,
          position          = new_pos,
          callback_function = callback
      })
  end
end

