function shuffle( t )
  local j
  for i = 0, 100 do
    math.random() math.random() math.random()
    math.randomseed( os.time() )
    math.random() math.random() math.random()
    if ( type(t) ~= "table" ) then
        return false
    end

    for i = #t, 2, -1 do
        j = math.random( i )
        t[i], t[j] = t[j], t[i]
    end
    math.random() math.random() math.random()
    Wait.frames(
      function()
        math.randomseed(os.time()) end, 1
    )
  end
  return t
end




